          arrExpr = l
            .split("=")[1]
            .replace(/^\[|\]$/gi, "")
            .split(/,\s*/g);
          result = varName + "=[];";
          arrExpr.forEach((expr) => {
            if (/^\.\.\./i.test(expr)) {
              result +=
                varName +
                "=" +
                varName +
                ".concat(" +
                expr.replace(/^\.\.\./i, "") +
                ");";
            } else {
